<?php
function codigoBarras(string $text): string {
 $patterns=json_decode('{"0": "bsbSBsBsb", "1": "BsbSbsbsB", "2": "bsBSbsbsB", "3": "BsBSbsbsb", "4": "bsbSBsbsB", "5": "BsbSBsbsb", "6": "bsBSBsbsb", "7": "bsbSbsBsB", "8": "BsbSbsBsb", "9": "bsBSbsBsb", "A": "BsbsbSbsB", "B": "bsBsbSbsB", "C": "BsBsbSbsb", "D": "bsbsBSbsB", "E": "BsbsBSbsb", "F": "bsBsBSbsb", "G": "bsbsbSBsB", "H": "BsbsbSBsb", "I": "bsBsbSBsb", "J": "bsbsBSBsb", "K": "BsbsbsbSB", "L": "bsBsbsbSB", "M": "BsBsbsbSb", "N": "bsbsBsbSB", "O": "BsbsBsbSb", "P": "bsBsBsbSb", "Q": "bsbsbsBSB", "R": "BsbsbsBSb", "S": "bsBsbsBSb", "T": "bsbsBsBSb", "U": "BSbsbsbsB", "V": "bSBsbsbsB", "W": "BSBsbsbsb", "X": "bSbsBsbsB", "Y": "BSbsBsbsb", "Z": "bSBsBsbsb", "-": "bSbsbsBsB", ".": "BSbsbsBsb", " ": "bSBsbsBsb", "*": "bSbsBsBsb", "$": "bSbSbSbsb", "/": "bSbSbsbSb", "+": "bSbsbSbSb", "%": "bsbSbSbSb"}',true);
 $text=strtoupper($text);if(!preg_match('~^[0-9A-Z .$/+%\-]{1,32}$~',$text)){return '';}
 $x=12;$bars='';foreach(str_split('*'.$text.'*') as $ch){foreach(str_split($patterns[$ch]) as $part){$width=ctype_upper($part)?3:1;if(strtolower($part)==='b'){$bars.='<rect x="'.$x.'" y="0" width="'.$width.'" height="34"/>';}$x+=$width;}$x++;}
 return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 '.($x+12).' 48" role="img" aria-label="Código '.htmlspecialchars($text,ENT_QUOTES,'UTF-8').'" class="barcode"><rect width="100%" height="100%" fill="white"/><g fill="black">'.$bars.'<text x="'.(($x+12)/2).'" y="45" text-anchor="middle" font-family="monospace" font-size="9">'.htmlspecialchars($text,ENT_QUOTES,'UTF-8').'</text></g></svg>';
}
